
(()=>{'use strict';
const el=id=>document.getElementById(id),panel=el('ntPanel'),home=el('wowQuietHome'),director=window.WOWNatuTeraDirector;if(!panel||!home||!director)return;
for(const [id,src]of [['wowQuietTera','data:image/png;base64,'],['wowQuietNatu','data:image/png;base64,']]){const b=el(id);const im=document.createElement('img');im.src=src;im.alt='';im.draggable=false;b.insertBefore(im,b.firstChild);}
const finish=document.createElement('button');finish.type='button';finish.textContent='Край на представянето';finish.dataset.quietAction='finish';finish.addEventListener('click',()=>{stop(true);director.close();el('wowFinish5')?.click();});
const welcome=document.createElement('button');welcome.type='button';welcome.textContent='Представи Нату и Тера';welcome.dataset.quietAction='welcome';
const container=panel.querySelector('.quiet-functions'),oldGrid=container.querySelector('.quiet-function-grid');oldGrid.append(finish,welcome);
const items=[...oldGrid.children],groups=[['Природа и зони',['birds','animals','plants','photos','zoneDocs','habitats','legacy0','legacy1','legacy2','archive']],['ТПУ и справки',['legacy3','legacy4','legacy5','legacy6','legacy7','registry']],['Навигация и представяне',['forward','home','presentation','intro','tera','classic','finish','welcome']]];
container.open=true;
for(const [label,keys]of groups){const group=document.createElement('details');group.className='quiet-group';const title=document.createElement('summary');title.textContent=label;const grid=document.createElement('div');grid.className='quiet-function-grid';group.append(title,grid);for(const key of keys){const node=items.find(n=>n.dataset.quietAction===key);if(node)grid.appendChild(node);}container.appendChild(group);group.addEventListener('toggle',()=>{if(group.open)for(const other of container.querySelectorAll('.quiet-group'))if(other!==group)other.open=false;});}
for(const extra of [...oldGrid.children])container.querySelector('.quiet-group .quiet-function-grid')?.appendChild(extra);oldGrid.remove();
const nav=container.querySelectorAll('.quiet-group .quiet-function-grid')[2];for(const b of [...panel.querySelectorAll('.ntShortcuts [data-cmd]')])if(['следващ','назад','спри'].some(w=>b.dataset.cmd.includes(w)))nav.appendChild(b);
for(const [id,text]of [['ntMic','Говори'],['ntInterrupt','Спри'],['ntHear','Представяне'],['ntClose','×'],['ntTera','Тера · Филм']])if(el(id))el(id).textContent=text;
const head=panel.querySelector('header b');if(head)head.textContent='Нату и Тера · Управление';
for(const b of container.querySelectorAll('[data-quiet-action="tera"]'))b.textContent='Тера · представителен филм';
const card=document.createElement('section');card.id='wowEntranceCard';card.hidden=true;card.setAttribute('aria-label','Представяне на Нату и Тера');card.innerHTML='<header><b id="wowEntranceSpeaker">Тера</b><button id="wowEntranceSkip" type="button">Пропусни</button></header><p id="wowEntranceText" role="status" aria-live="polite"></p><div id="wowEntranceChoices" hidden><button id="wowEntranceFilm" type="button">Представителният филм</button><button id="wowEntranceNatu" type="button">С Нату</button></div>';document.body.appendChild(card);
const lines=[['Тера','Здравей! Аз съм Тера — твоята видео кралица! С моя представителен филм ще ти покажа панорамата на ТПУ Пловдив — планини, води, растения и животни.'],['Тера','А това е моят приятел Нату! С него можеш да разгледаш ТПУ отвсякъде — зони, карти, снимки и документи. Избери вид и открий полето „Какво знаеш за мен?“.'],['Нату','Здравей! Натисни ме, избери зона или ми кажи какво искаш да откриеш. Ще ти помогна да намериш пътя!'],['Тера','С какво започваме — моя представителен филм за ТПУ Пловдив или откривателско пътешествие с Нату?']];
let epoch=0,timer=null,utterance=null,active=false,seen=false;
try{seen=sessionStorage.getItem('wowAnimatedEntranceV1')==='yes';}catch(e){}
function cancelAudio(){try{if(utterance){utterance.onend=null;utterance.onerror=null;window.speechSynthesis?.cancel();utterance=null;}}catch(e){}}
function stop(pauseMotion=false){epoch++;clearTimeout(timer);timer=null;active=false;cancelAudio();card.hidden=true;document.body.classList.remove('wow-intro-flying','wow-speaker-natu','wow-intro-running');if(pauseMotion)document.body.classList.add('wow-motion-paused');}
function presentStep(i,token,done){if(token!==epoch||!active)return;if(i>=lines.length){active=false;document.body.classList.remove('wow-intro-flying','wow-speaker-natu','wow-intro-running');el('wowEntranceChoices').hidden=false;if(done)done();return;}
const [who,text]=lines[i];el('wowEntranceSpeaker').textContent=who;el('wowEntranceText').textContent=text;document.body.classList.toggle('wow-intro-flying',i<2);document.body.classList.toggle('wow-speaker-natu',who==='Нату');
let advanced=false;const next=()=>{if(advanced||token!==epoch||!active)return;advanced=true;clearTimeout(timer);cancelAudio();presentStep(i+1,token,done);};
const readMs=Math.max(5500,Math.min(15000,text.split(/\s+/).length*340));
try{const voice=window.speechSynthesis?.getVoices().find(v=>/^bg(?:-|$)/i.test(v.lang));if(voice&&window.SpeechSynthesisUtterance){utterance=new SpeechSynthesisUtterance(text);utterance.lang='bg-BG';utterance.voice=voice;utterance.rate=.95;utterance.onend=next;utterance.onerror=()=>{timer=setTimeout(next,readMs);};window.speechSynthesis.speak(utterance);timer=setTimeout(next,Math.max(18000,readMs*2));return;}}catch(e){}
timer=setTimeout(next,readMs);
}
function start(force=false,done){if(!document.body.classList.contains('wow-quiet'))return;if(seen&&!force)return;window.tpuVoice?.stop();director.interrupt?.();stop(false);seen=true;try{sessionStorage.setItem('wowAnimatedEntranceV1','yes');}catch(e){}if(window.WOWTeraVideo?.isOpen())window.WOWTeraVideo.close();document.body.classList.remove('wow-motion-paused');active=true;const token=++epoch;card.hidden=false;el('wowEntranceChoices').hidden=true;document.body.classList.add('wow-intro-running');presentStep(0,token,done);}
window.WOWEntrance=Object.freeze({start,stop,isActive:()=>active,hasPresented:()=>seen});
el('wowEntranceSkip').addEventListener('click',()=>stop(true));el('wowEntranceFilm').addEventListener('click',()=>{stop(false);window.WOWTeraVideo?.open();});el('wowEntranceNatu').addEventListener('click',()=>{stop(false);director.open();});welcome.addEventListener('click',()=>{director.close();start(true);});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='ntHear'){e.preventDefault();e.stopImmediatePropagation();director.close();start(true);return;}if(b.dataset.quietAction==='welcome')return;if(b.id==='wowEntranceSkip')return;if(b.id==='ntInterrupt'||b.dataset.cmd==='спри'){stop(true);return;}if(['wowQuietNatu','wowQuietTera','ntGo','ntMic'].includes(b.id)||b.dataset.cmd||b.dataset.quietAction)stop(false);},true);
window.addEventListener('keydown',e=>{if(active&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();stop(true);}},true);
const watch=new MutationObserver(()=>{if(!document.body.classList.contains('wow-quiet')){if(active||!card.hidden)stop(false);return;}if(!seen)start(false);});watch.observe(document.body,{attributes:true,attributeFilter:['class']});if(document.body.classList.contains('wow-quiet'))start(false);
})();

